def find_shortest_path_length(t, n, queries):
    def get_vertex_count(k):
        if k == 0:
            return 1
        elif k == 1:
            return 2
        else:
            a, b = 1, 2
            for _ in range(2, k + 1):
                a, b = b, a + b
            return b

    def find_path_length(a, b, n):
        if a == b:
            return 0
        if a > b:
            a, b = b, a

        vertex_count = get_vertex_count(n)
        if a <= vertex_count // 2 and b > vertex_count // 2:
            return min(b - a, a + vertex_count - b + 1)
        elif a > vertex_count // 2 and b > vertex_count // 2:
            return b - a
        else:
            return a + vertex_count - b

    vertex_count = get_vertex_count(n)
    results = []
    for a, b in queries:
        if a > vertex_count or b > vertex_count:
            continue
        results.append(find_path_length(a, b, n))

    return results

